def choose_move(observation):
    x, y = observation['self_position']
    width = observation['grid_width']
    height = observation['grid_height']
    obstacles = set(observation['obstacles'])
    resources = observation['resources']
    opponent = observation['opponent_position']
    def valid(pos):
        return (0 <= pos[0] < width and 0 <= pos[1] < height and
                pos not in obstacles)
    def move(dx, dy):
        new_x, new_y = x + dx, y + dy
        if valid((new_x, new_y)):
            return [dx, dy]
        return [0, 0]
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    min_dist = None
    best_move = [0,0]
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if not valid((nx, ny)):
            continue
        dist = abs(nx - opponent[0]) + abs(ny - opponent[1])
        if min_dist is None or dist < min_dist:
